#include "timeline_object.hpp"
#include <QUuid>
#include <set>
#include <limits>
namespace spatial {
Light* timelineLight(StageModel&m,int h){if(!lightObject(h))return nullptr;auto i=size_t(lightHandleBase-h);return i==0?&m.light:i<=m.extraLights.size()?&m.extraLights[i-1]:nullptr;}
const Light* timelineLight(const StageModel&m,int h){return timelineLight(const_cast<StageModel&>(m),h);}
FxInstance* timelineFx(StageModel&m,int h){if(!fxObject(h))return nullptr;auto n=size_t(int64_t(fxHandleBase)-h),l=n/256,d=n%256;if(l>=m.layers.size()||d>=fxCatalog().size())return nullptr;return findFx(m.layers[l].fx,fxCatalog()[d].id);}
const FxInstance* timelineFx(const StageModel&m,int h){return timelineFx(const_cast<StageModel&>(m),h);}
std::vector<TimelineObject> timelineObjects(const StageModel&m){
 std::vector<TimelineObject> out{{-1,{TimelineKind::Camera,"camera",{}},"摄像机 · 视角"},{-2,{TimelineKind::Composite,"composite",{}},"全画面合成"}};
 for(size_t i=0;i<m.layers.size();++i){const auto&l=m.layers[i];out.push_back({int(i),{TimelineKind::Layer,l.instanceId,{}},layerDisplayName(l),l.enabled&&l.visible});
  for(size_t j=0;j<fxCatalog().size();++j){const auto&d=fxCatalog()[j];const auto*f=findFx(l.fx,d.id);if(f&&(f->enabled||!f->animation.empty()))out.push_back({fxHandleBase-int(i*256+j),{TimelineKind::Fx,d.id,l.instanceId},"  FX · "+d.name,l.fx.attached&&l.fx.groups[size_t(d.group-1)]&&f->enabled});}}
 for(size_t i=0;i<m.geometries.size();++i){const auto&g=m.geometries[i];out.push_back({-3-int(i),{TimelineKind::Geometry,g.instanceId,{}},"图形 · "+g.label,g.enabled&&g.visible});}
 if(m.light.present||m.light.enabled||m.light.visible||!m.light.animation.empty())out.push_back({lightHandleBase,{TimelineKind::Light,m.light.instanceId,{}},"灯光 · "+m.light.label,m.light.enabled});
 for(size_t i=0;i<m.extraLights.size();++i){const auto&l=m.extraLights[i];out.push_back({lightHandleBase-1-int(i),{TimelineKind::Light,l.instanceId,{}},"灯光 · "+l.label,l.enabled});}return out;
}
bool validObject(const StageModel&m,int h){return h==-1||h==-2||(h>=0&&size_t(h)<m.layers.size())||(geometryObject(h)&&size_t(-3-int64_t(h))<m.geometries.size())||timelineLight(m,h)||timelineFx(m,h);}
std::optional<int> resolveTimelineObject(const StageModel&m,const TimelineRef&r){for(const auto&o:timelineObjects(m))if(o.ref.kind==r.kind&&o.ref.id==r.id&&o.ref.owner==r.owner)return o.handle;return {};}
std::vector<TimelineParameter> objectParameters(const StageModel&m,int h){
 std::vector<TimelineParameter> out;if(!validObject(m,h))return out;
 auto add=[&](std::string id,std::string label,double lo,double hi,double sl,double sh,bool discrete=false){out.push_back({std::move(id),std::move(label),lo,hi,sl,sh,discrete});};
 auto colors=[&](const std::string&prefix,const std::string&label){add(prefix+".r",label+" R",0,1,0,1);add(prefix+".g",label+" G",0,1,0,1);add(prefix+".b",label+" B",0,1,0,1);};
 if(const auto*f=timelineFx(m,h)){const auto*d=fxDefinition(f->id);if(!d)return out;add("strength","混合强度",0,1,0,1);for(const auto&p:d->parameters){add(p.key,p.label,p.minimum,p.maximum,p.minimum,p.maximum,!p.choices.empty()||p.key=="reverse");out.back().integer=out.back().discrete||p.key=="count"||p.key=="seed"||p.key=="segments";}if(d->color)colors("color","效果颜色");if(d->color2)colors("color2","辅助颜色");return out;}
 if(timelineLight(m,h)){
  for(const auto&p:parameters())if(std::string(p.id)=="x"||std::string(p.id)=="y"||std::string(p.id)=="z")add(p.id,p.label,p.minimum,p.maximum,p.sliderMin,p.sliderMax);
  add("intensity","强度",0,10,0,10);add("range","范围",10,100000,10,5000);add("ambient","环境补光",0,2,0,2);add("shadowOpacity","阴影强度",0,1,0,1);add("receiverZ","接收面深度",-100000,100000,-2000,2000);add("size","灯光尺寸",0,2000,0,2000);add("falloff","距离衰减",.1,8,.1,8);add("softness","软阴影半径",0,300,0,300);add("rim","轮廓光强度",0,5,0,5);add("rimWidth","轮廓光宽度",.01,100,.01,100);add("rimSoftness","轮廓光柔和度",0,1,0,1);colors("color","灯光颜色");colors("shadowColor","阴影颜色");return out;
 }
 for(const auto&p:parameters()){std::string id=p.id;bool valid=h==-2?(id=="sx"||id=="sy"||id=="opacity"):h==-1?(id!="sx"&&id!="sy"&&id!="opacity"):(id=="x"||id=="y"||id=="z"||id=="rx"||id=="ry"||id=="rz"||id=="sx"||id=="sy"||id=="opacity");if(valid)add(p.id,p.label,p.minimum,p.maximum,p.sliderMin,p.sliderMax);}return out;
}
std::optional<TimelineParameter> objectParameter(const StageModel&m,int h,const std::string&id){for(auto&p:objectParameters(m,h))if(p.id==id)return p;return {};}
Animation& objectAnimation(StageModel&m,int h){if(auto*l=timelineLight(m,h))return l->animation;if(auto*f=timelineFx(m,h))return f->animation;return h==-1?m.cameraAnimation:h==-2?m.compositeAnimation:geometryObject(h)?m.geometries.at(size_t(-3-int64_t(h))).animation:m.layers.at(size_t(h)).animation;}
const Animation& objectAnimation(const StageModel&m,int h){return objectAnimation(const_cast<StageModel&>(m),h);}
bool objectLocked(const StageModel&m,int h){if(!validObject(m,h))return true;if(auto*l=timelineLight(m,h))return l->locked;if(auto*f=timelineFx(m,h))return f->locked||m.layers[size_t(int64_t(fxHandleBase)-h)/256].locked;return h==-1?m.cameraLocked:h==-2?m.compositeLocked:geometryObject(h)?m.geometries[size_t(-3-int64_t(h))].locked:m.layers[size_t(h)].locked;}
void setObjectLocked(StageModel&m,int h,bool on){if(auto*l=timelineLight(m,h))l->locked=on;else if(auto*f=timelineFx(m,h))f->locked=on;else if(h==-1)m.cameraLocked=on;else if(h==-2)m.compositeLocked=on;else if(geometryObject(h))m.geometries[size_t(-3-int64_t(h))].locked=on;else if(h>=0&&size_t(h)<m.layers.size())m.layers[size_t(h)].locked=on;}
namespace {
double* colorAddress(Vec3&v,const std::string&s){return s=="r"?&v.x:s=="g"?&v.y:s=="b"?&v.z:nullptr;}
double* address(StageModel&m,int h,const std::string&id){
 if(!validObject(m,h))return nullptr;
 if(auto*f=timelineFx(m,h)){if(id=="strength")return &f->strength;if(id.rfind("color.",0)==0)return colorAddress(f->color,id.substr(6));if(id.rfind("color2.",0)==0)return colorAddress(f->color2,id.substr(7));const auto*d=fxDefinition(f->id);for(size_t i=0;d&&i<d->parameters.size()&&i<f->values.size();++i)if(d->parameters[i].key==id)return &f->values[i];return nullptr;}
 if(auto*l=timelineLight(m,h)){if(id=="x")return &l->position.x;if(id=="y")return &l->position.y;if(id=="z")return &l->position.z;if(id.rfind("color.",0)==0)return colorAddress(l->color,id.substr(6));if(id.rfind("shadowColor.",0)==0)return colorAddress(l->shadowColor,id.substr(12));
  const std::pair<const char*,double*> fields[]={{"intensity",&l->intensity},{"range",&l->range},{"ambient",&l->ambient},{"shadowOpacity",&l->shadowOpacity},{"receiverZ",&l->receiverZ},{"size",&l->size},{"falloff",&l->falloff},{"softness",&l->softness},{"rim",&l->rim},{"rimWidth",&l->rimWidth},{"rimSoftness",&l->rimSoftness}};for(auto&p:fields)if(id==p.first)return p.second;return nullptr;}
 if(geometryObject(h)){auto&g=m.geometries.at(size_t(-3-int64_t(h)));if(id=="x")return &g.plane.position.x;if(id=="y")return &g.plane.position.y;if(id=="z")return &g.plane.position.z;if(id=="rx")return &g.plane.rotation.x;if(id=="ry")return &g.plane.rotation.y;if(id=="rz")return &g.plane.rotation.z;if(id=="sx")return &g.plane.scaleX;if(id=="sy")return &g.plane.scaleY;if(id=="opacity")return &g.opacity;return nullptr;}
 if(h==-2){if(id=="sx")return &m.outputScaleX;if(id=="sy")return &m.outputScaleY;if(id=="opacity")return &m.outputOpacity;return nullptr;}
 Vec3*p=h==-1?&m.camera.position:&m.layers.at(size_t(h)).plane.position;Vec3*r=h==-1?&m.camera.rotation:&m.layers.at(size_t(h)).plane.rotation;
 if(id=="x")return &p->x;if(id=="y")return &p->y;if(id=="z")return &p->z;if(id=="rx")return &r->x;if(id=="ry")return &r->y;if(id=="rz")return &r->z;if(h==-1&&id=="fov")return &m.camera.fov;
 if(h>=0){auto&l=m.layers[size_t(h)];if(id=="sx")return &l.plane.scaleX;if(id=="sy")return &l.plane.scaleY;if(id=="opacity")return &l.opacity;}
 auto&o=h==-1?m.cameraOrbit:m.layers[size_t(h)].orbit;if(id=="tx")return h==-1?&m.target.x:&o.x;if(id=="ty")return h==-1?&m.target.y:&o.y;if(id=="tz")return h==-1?&m.target.z:&o.z;if(id=="radius")return &o.radius;if(id=="yaw")return &o.yaw;if(id=="pitch")return &o.pitch;return nullptr;
}
}
double baseValue(const StageModel&m,int h,const std::string&p){auto*v=address(const_cast<StageModel&>(m),h,p);return v?*v:0;}
void setBaseValue(StageModel&m,int h,const std::string&p,double v){auto meta=objectParameter(m,h,p);if(!meta||!std::isfinite(v))return;auto*ptr=address(m,h,p);if(ptr)*ptr=std::clamp((meta->discrete||meta->integer)?std::round(v):v,meta->minimum,meta->maximum);}
double evaluatedValue(const StageModel&m,int h,const std::string&p,TimeUs t,bool animate){double b=baseValue(m,h,p);if(!animate||!validObject(m,h))return b;const auto&a=objectAnimation(m,h);auto c=a.find(p);if(c==a.end())return b;auto meta=objectParameter(m,h,p);double v=b;if(meta&&meta->discrete&&c->second.enabled&&!c->second.keys().empty()){const auto&keys=c->second.keys();auto i=std::upper_bound(keys.begin(),keys.end(),t,[](TimeUs n,const AnimKey&k){return n<k.time;});v=(i==keys.begin()?keys.front():*(i-1)).value;}else v=c->second.value(t,b);if(!std::isfinite(v))return b;return meta?std::clamp((meta->discrete||meta->integer)?std::round(v):v,meta->minimum,meta->maximum):b;}
bool writeAnimatedValue(StageModel&m,int h,const std::string&p,double v,std::string&error){auto meta=objectParameter(m,h,p);if(!meta||!std::isfinite(v)){error="参数不可用";return false;}if(objectLocked(m,h)){error="对象已锁定";return false;}auto&a=objectAnimation(m,h);auto it=a.find(p);TimeUs t=toTime(m.timelinePosition);if(it!=a.end()&&(it->second.locked||(t&&it->second.enabled&&!m.autoKey&&!it->second.contains(t)))){error="参数已锁定或当前位置没有关键帧；先记录关键帧，或开启自动关键帧。";return false;}
 v=std::clamp((meta->discrete||meta->integer)?std::round(v):v,meta->minimum,meta->maximum);auto&c=a[p];if(c.enabled||(t&&m.autoKey)){if(c.keys().empty()&&t)c.put({0,baseValue(m,h,p)});AnimKey k{t,v};for(auto&old:c.keys())if(old.time==t){k=old;k.value=v;break;}if(meta->discrete)k.interpolation=Interpolation::Hold;c.enabled=true;c.put(k);}else setBaseValue(m,h,p,v);m.playing=false;m.timelinePreview=true;return true;}
Light evaluateLight(const StageModel&m,int h,TimeUs t,bool motion){auto*original=timelineLight(m,h);Light l=original?*original:Light{};if(!original||!motion||l.animation.empty())return l;
 for(const auto&channel:l.animation){const auto&id=channel.first;double v=evaluatedValue(m,h,id,t);double*ptr=nullptr;if(id=="x")ptr=&l.position.x;else if(id=="y")ptr=&l.position.y;else if(id=="z")ptr=&l.position.z;else if(id.rfind("color.",0)==0)ptr=colorAddress(l.color,id.substr(6));else if(id.rfind("shadowColor.",0)==0)ptr=colorAddress(l.shadowColor,id.substr(12));else{const std::pair<const char*,double*> fields[]={{"intensity",&l.intensity},{"range",&l.range},{"ambient",&l.ambient},{"shadowOpacity",&l.shadowOpacity},{"receiverZ",&l.receiverZ},{"size",&l.size},{"falloff",&l.falloff},{"softness",&l.softness},{"rim",&l.rim},{"rimWidth",&l.rimWidth},{"rimSoftness",&l.rimSoftness}};for(auto&p:fields)if(id==p.first)ptr=p.second;}if(ptr)*ptr=v;}return l;
}
FxStack evaluateLayerFx(const StageModel&m,size_t i,TimeUs t,bool motion){auto out=m.layers.at(i).fx;if(!motion)return out;for(auto&f:out.effects){if(f.animation.empty())continue;const auto*d=fxDefinition(f.id);if(!d)continue;const auto n=size_t(d-&fxCatalog().front());const int h=fxHandleBase-int(i*256+n);for(const auto&channel:f.animation){const auto&id=channel.first;double v=evaluatedValue(m,h,id,t);if(id=="strength")f.strength=v;else if(id.rfind("color.",0)==0){if(auto*p=colorAddress(f.color,id.substr(6)))*p=v;}else if(id.rfind("color2.",0)==0){if(auto*p=colorAddress(f.color2,id.substr(7)))*p=v;}else for(size_t j=0;j<d->parameters.size()&&j<f.values.size();++j)if(id==d->parameters[j].key)f.values[j]=v;}}return out;}
void sanitizeObjectAnimations(StageModel&m){for(const auto&o:timelineObjects(m)){auto&a=objectAnimation(m,o.handle);for(auto i=a.begin();i!=a.end();){auto meta=objectParameter(m,o.handle,i->first);if(!meta){i=a.erase(i);continue;}Curve next=i->second;for(auto k:i->second.keys()){k.value=std::clamp(k.value,meta->minimum,meta->maximum);if(meta->discrete||meta->integer)k.value=std::round(k.value);if(meta->discrete)k.interpolation=Interpolation::Hold;next.put(k);}i->second=std::move(next);++i;}}}
AnimationPaste prepareAnimationPaste(const StageModel&m,int h,const Animation&source,TimeUs at){AnimationPaste p;TimeUs first=INT64_MAX,last=0;for(auto&v:source)for(auto&k:v.second.keys()){first=std::min(first,k.time);last=std::max(last,k.time);}if(first==INT64_MAX)return p;const auto delta=std::max(TimeUs(0),at)-first;p.first=first+delta;p.last=last+delta;
 for(auto&v:source){auto meta=objectParameter(m,h,v.first);if(!meta){p.skipped.push_back(v.first);continue;}const auto&dst=objectAnimation(m,h);auto it=dst.find(v.first);if(objectLocked(m,h)||(it!=dst.end()&&it->second.locked)){p.skipped.push_back(v.first+"（已锁定）");continue;}Curve c=v.second;c.clear();c.enabled=v.second.enabled;c.shortest=v.second.shortest;c.locked=false;for(auto k:v.second.keys()){if(k.time>INT64_MAX-std::max(TimeUs(0),delta)){p.skipped.push_back(v.first+"（时间溢出）");c.clear();break;}k.time+=delta;k.value=std::clamp((meta->discrete||meta->integer)?std::round(k.value):k.value,meta->minimum,meta->maximum);if(meta->discrete)k.interpolation=Interpolation::Hold;c.put(k);}if(c.keys().empty())continue;if(it!=dst.end())for(auto&k:it->second.keys())if(k.time>=p.first&&k.time<=p.last)p.conflict=true;p.tracks[v.first]=std::move(c);}return p;
}
bool pasteObjectAnimation(StageModel&m,int h,const AnimationPaste&p){if(!validObject(m,h)||objectLocked(m,h)||p.tracks.empty())return false;auto&a=objectAnimation(m,h);for(auto&v:p.tracks)if(a.count(v.first)&&a.at(v.first).locked)return false;for(auto&v:p.tracks){const bool existed=a.count(v.first)&&!a.at(v.first).keys().empty();auto&c=a[v.first];std::vector<TimeUs>erase;for(auto&k:c.keys())if(k.time>=p.first&&k.time<=p.last)erase.push_back(k.time);for(auto t:erase)c.erase(t);if(!existed){c.enabled=v.second.enabled;c.shortest=v.second.shortest;}for(auto k:v.second.keys())c.put(k);}return true;}
bool duplicateTimelineLayer(StageModel&m,const Layer&source,std::string&error){if(m.layers.size()>=32){error="舞台最多支持 32 个素材实例";return false;}Layer l=source;l.instanceId=QUuid::createUuid().toString(QUuid::WithoutBraces).toStdString();l.instanceNumber=1;for(const auto&old:m.layers)if(sameSourceItem(old,l))l.instanceNumber=std::max(l.instanceNumber,old.instanceNumber+1);l.depthOrder=int(m.layers.size());l.locked=false;for(auto&f:l.fx.effects)if(f.reference==source.instanceId)f.reference=l.instanceId;m.layers.push_back(std::move(l));return true;}
}
